mapper.select:
SELECT COUNT(*)
FROM recommend r
JOIN member m ON r.member_id = m.member_id
WHERE r.board_type = 'SALE'
  AND r.board_id = #{tradeId}
  AND m.userid = #{userid}

mapper.insert:
INSERT INTO recommend (member_id, board_type, board_id)
SELECT member_id, 'SALE', #{tradeId}
FROM member
WHERE userid = #{userid}

mapper.update:
UPDATE saletrade_board
SET recommend_cnt = recommend_cnt + 1
WHERE trade_id = #{tradeId}

mapper.select:
SELECT recommend_cnt
FROM saletrade_board
WHERE trade_id = #{tradeId}
